    std::cout << "edit " << edited << ":";
    int total = 0;
    for (std::size_t i = 0; i < kSources.size(); ++i) {
        bool affected = kSources[i] == edited;
        for (const auto& header : kIncludes[i]) {
            if (header == edited) {
                affected = true;
            }
        }
        if (affected) {
            std::cout << ' ' << kSources[i];
            total += kLines[i];
        }
    }
    std::cout << " (" << total << " lines)\n";
}

