#include <iostream>
#include <string>
#include <vector>

// Each rule: the target, then its prerequisites, in the order make visits them.
const std::vector<std::vector<std::string>> kRules = {
    {"build/fees.o", "src/fees.cpp", "include/fees.h"},
    {"build/main.o", "src/main.cpp", "include/fees.h", "include/quote.h"},
    {"build/quote.o", "src/quote.cpp", "include/quote.h"},
    {"app", "build/fees.o", "build/main.o", "build/quote.o"},
};
const std::vector<std::string> kFiles = {
    "src/fees.cpp", "src/main.cpp", "src/quote.cpp", "include/fees.h", "include/quote.h",
    "build/fees.o", "build/main.o", "build/quote.o", "app",
};

int indexOf(std::string file) {
    for (std::size_t i = 0; i < kFiles.size(); ++i) {
        if (kFiles[i] == file) {
            return static_cast<int>(i);
        }
    }
    return -1;
}

int main() {
    // Modification times, in seconds, in kFiles order: the last build
    // wrote the objects and app at 100 to 103, then quote.h was saved at 200.
    std::vector<int> mtime = {10, 12, 11, 20, 200, 100, 101, 102, 103};
    int now = 300;
    for (const auto& rule : kRules) {
        const int target = indexOf(rule[0]);
        std::string newer;
        for (std::size_t p = 1; p < rule.size(); ++p) {
            if (newer.empty() && mtime[indexOf(rule[p])] > mtime[target]) {
                newer = rule[p];
            }
        }
        if (newer.empty()) {
            std::cout << rule[0] << " is up to date\n";
        } else {
            std::cout << "rebuild " << rule[0] << " (" << newer << " is newer)\n";
            mtime[target] = now;  // the rebuilt file is the newest of all
            ++now;
        }
    }
    return 0;
}

