#include <iostream>
#include <string>

// ---- include/quote.h ----
namespace mkt {
double mid(double bid, double ask);
double spreadBps(double bid, double ask);
}  // namespace mkt

// ---- src/quote.cpp, in the quotes_core library ----
namespace mkt {
double mid(double bid, double ask) {
    return (bid + ask) / 2.0;
}
double spreadBps(double bid, double ask) {
    return (ask - bid) / mid(bid, ask) * 10'000.0;
}
}  // namespace mkt

// ---- tests/test_quote.cpp ----
bool near(double a, double b) {
    return a - b < 1e-9 && b - a < 1e-9;  // within 1e-9 either way
}

bool check(bool ok, std::string what) {
    std::cout << (ok ? "pass: " : "FAIL: ") << what << '\n';
    return ok;
}

int main() {
    int failures = 0;
    if (!check(mkt::mid(100.0, 102.0) == 101.0, "mid of 100 and 102 is 101")) {
        ++failures;
    }
    if (!check(mkt::spreadBps(101.0, 101.0) == 0.0, "a locked quote has no spread")) {
        ++failures;
    }
    if (!check(near(mkt::spreadBps(99.0, 101.0), 200.0), "99 and 101 are 200 bps apart")) {
        ++failures;
    }
    std::cout << failures << " failed\n";
    return failures == 0 ? 0 : 1;  // ctest reads only this
}

